"""tests/fixtures/naver_item/*.html 생성기 (일회성).

네이버 종목 상세 페이지의 **구조만** 본뜬 합성 HTML 입니다. 실제 페이지를 다시 긁으면
§0-3-2(상대 서버에 무리를 주지 않는다)에 어긋나므로, 저장소가 이미 쓰던 방식
(`tests/test_collector_kospi200_ranking.py` 의 `_FAKE_ASIDE_ONLY_HTML` 등)을 따릅니다.
한계는 `tests/_naver_item_baseline.py` 머리말에 명시돼 있습니다.
"""
from pathlib import Path

OUT = Path(__file__).parent
OUT.mkdir(parents=True, exist_ok=True)


def aside(rows):
    body = "\n".join(f"<tr><th>{th}</th><td>{td}</td></tr>" for th, td in rows)
    return f'<div class="aside_invest_info"><table>\n{body}\n</table></div>'


def fin_table(headers, rows):
    head = "".join(f"<th>{h}</th>" for h in headers)
    body = "\n".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
    return f"<table>\n<tr>{head}</tr>\n{body}\n</table>"


def page(*parts, note=""):
    return (f"<!-- 합성 픽스처 (네이버 구조 모방). {note} -->\n"
            "<html><body>\n" + "\n".join(parts) + "\n</body></html>\n")


def wise(headers, rows, note=""):
    return (f"<!-- 합성 픽스처 (WiseReport 구조 모방). {note} -->\n"
            "<html><body>\n" + fin_table(headers, rows) + "\n</body></html>\n")


ASIDE_NORMAL = [
    ("PERlEPS(2026.06)", "12.34배 l 5,678원"),
    ("추정PERlEPS", "10.00배 l 7,000원"),
    ("PBRlBPS", "1.23배 l 50,000원"),
    ("배당수익률", "2.50%"),
    ("상장주식수", "59,700,000"),
]
FIN_HEAD = ["주요재무정보", "2024.12", "2025.12", "2026.12(E)"]

W = {}

# ── 000010 정상 ───────────────────────────────────────────────────────────────
W["000010.main.html"] = page(
    aside(ASIDE_NORMAL),
    fin_table(FIN_HEAD, [
        ["매출액", "100", "200", "300"],
        ["영업이익", "10", "20", "30"],
        ["ROE(지배주주)", "8.1", "9.2", "10.5"],
        ["주당배당금", "1,000", "1,200", "1,300"],
    ]),
    note="정상 — 모든 구획이 값을 채우는 기준 사례")
W["000010.wisereport.html"] = wise(
    ["항목", "2024.12", "2025.12"], [["EV/EBITDA", "5.5", "6.7"]],
    note="EV/EBITDA 정상 수집")

# ── 000020 적자 (부호 보존, 2차 감사 1-1) ─────────────────────────────────────
W["000020.main.html"] = page(
    aside([
        ("PERlEPS(2026.06)", "-49.26배 l -6,851원"),
        ("추정PERlEPS", "N/A"),
        ("PBRlBPS", "0.80배 l 12,000원"),
        ("배당수익률", "N/A"),
        ("상장주식수", "12,300,000"),
    ]),
    fin_table(FIN_HEAD, [
        ["매출액", "50", "40", "45"],
        ["주당배당금", "-", "-", "-"],
    ]),
    note="적자 — 예전 정규식이 '-' 를 버려 흑자로 둔갑시켰던 사례")

# ── 000030 무배당 확정 (재감사 H3) ────────────────────────────────────────────
W["000030.main.html"] = page(
    aside([
        ("PERlEPS(2026.06)", "8.00배 l 2,000원"),
        ("PBRlBPS", "0.70배 l 22,000원"),
        ("배당수익률", "N/A"),
        ("상장주식수", "8,800,000"),
    ]),
    fin_table(FIN_HEAD, [
        ["매출액", "70", "80", "90"],
        ["주당배당금", "-", "-", "-"],
    ]),
    note="무배당 확정 — 재무제표 전부 '-' + 배당수익률 명시적 N/A, 두 근거가 모두 있음")

# ── 000040 DPS 셀 파싱 오류 (재감사 H2) ───────────────────────────────────────
W["000040.main.html"] = page(
    aside([
        ("PERlEPS(2026.06)", "15.00배 l 3,000원"),
        ("배당수익률", "N/A"),
        ("상장주식수", "5,000,000"),
    ]),
    fin_table(FIN_HEAD, [
        ["매출액", "10", "20", "30"],
        ["주당배당금", "미공시", "미공시", "미공시"],
    ]),
    note="파싱 실패를 '배당 없음'이라는 실측 사실로 승격하면 안 되는 사례")

# ── 000050 aside 만 (재감사 H1) ───────────────────────────────────────────────
W["000050.main.html"] = page(
    aside(ASIDE_NORMAL),
    note="재무제표 구획이 없어도 aside 에서 읽은 값은 버리지 않아야 함")

# ── 000060 표가 하나도 없음 ───────────────────────────────────────────────────
W["000060.main.html"] = (
    "<!-- 합성 픽스처. 표 자체가 없어 pd.read_html 이 ValueError 를 던지는 페이지 -->\n"
    '<html><body><div class="aside_invest_info">'
    "<tr><th>PERlEPS(2026.06)</th><td>12.34배 l 5,678원</td></tr>"
    "<tr><th>상장주식수</th><td>59,700,000</td></tr>"
    "</div></body></html>\n")

# ── 000070 자본잠식 (PBR 음수) ────────────────────────────────────────────────
W["000070.main.html"] = page(
    aside([
        ("PERlEPS(2026.06)", "5.00배 l 1,000원"),
        ("PBRlBPS", "-1.10배 l -3,000원"),
        ("배당수익률", "1.10%"),
        ("상장주식수", "3,300,000"),
    ]),
    fin_table(FIN_HEAD, [["매출액", "1", "2", "3"], ["주당배당금", "50", "60", "70"]]),
    note="자본잠식 — BPS 가 음수라 PBR 도 음수, 부호를 보존해야 함")

# ── 000080 상장주식수 산티 실패 ───────────────────────────────────────────────
W["000080.main.html"] = page(
    aside([
        ("PERlEPS(2026.06)", "9.00배 l 900원"),
        ("배당수익률", "0.50%"),
        ("상장주식수", "1,234"),          # 100만 주 미만 → 산티 실패
    ]),
    fin_table(FIN_HEAD, [["매출액", "5", "6", "7"], ["주당배당금", "10", "10", "10"]]),
    note="구 버전이 외국인소진율 등 다른 숫자를 상장주식수로 오인하던 지점")

# ── 000090 Forward ROE 이상치 ─────────────────────────────────────────────────
W["000090.main.html"] = page(
    aside(ASIDE_NORMAL),
    fin_table(FIN_HEAD, [
        ["매출액", "1", "2", "3"],
        ["ROE(지배주주)", "8.0", "9.0", "412.0"],   # ±300% 초과 → 제외
        ["주당배당금", "100", "100", "100"],
    ]),
    note="상식 밖 추정 ROE 는 값을 지우지 않고 '제외'로 기록")

# ── 000100 연간 컬럼 헤더 분류 실패 (SPEC §2-1) ───────────────────────────────
W["000100.main.html"] = page(
    aside([("배당수익률", "N/A"), ("상장주식수", "2,000,000")]),
    fin_table(["주요재무정보", "1분기", "2분기"], [
        ["매출액", "1", "2"],
        ["주당배당금", "100", "200"],
    ]),
    note="연간 컬럼을 특정 못 하면 iloc 폴백 없이 DPS 미수집으로 남겨야 함")

# ── 00011K 우선주 → 부모 000110 에서 상속 (재감사 H12) ────────────────────────
W["00011K.main.html"] = page(
    aside([
        ("PERlEPS(2026.06)", "7.00배 l 1,400원"),
        ("배당수익률", "N/A"),
        ("상장주식수", "1,500,000"),
    ]),
    fin_table(FIN_HEAD, [["매출액", "1", "2", "3"], ["주당배당금", "-", "-", "-"]]),
    note="우선주 — 자기 DPS 는 없고 부모(000110)에서 상속받아야 함")
W["000110.main.html"] = page(
    aside([
        ("PERlEPS(2026.06)", "7.50배 l 1,300원"),
        ("배당수익률", "3.00%"),
        ("상장주식수", "20,000,000"),
    ]),
    fin_table(FIN_HEAD, [["매출액", "1", "2", "3"], ["주당배당금", "800", "850", "900"]]),
    note="위 우선주의 보통주 — 마스터에서 STOCK 으로 확인된 부모")

# ── 00012K 우선주 → 부모가 STOCK 이 아님 → 상속 보류 ──────────────────────────
W["00012K.main.html"] = page(
    aside([("배당수익률", "N/A"), ("상장주식수", "1,100,000")]),
    fin_table(FIN_HEAD, [["매출액", "1", "2", "3"], ["주당배당금", "-", "-", "-"]]),
    note="부모(000120)가 마스터에서 ETF — 추측 코드를 검증 없이 상속하면 안 되는 사례")

# ── 000130 빈 페이지 ──────────────────────────────────────────────────────────
W["000130.main.html"] = (
    "<!-- 합성 픽스처. aside 도 표도 없는 페이지 -->\n"
    "<html><body><p>내용 없음</p></body></html>\n")

for name, html in W.items():
    (OUT / name).write_text(html, encoding="utf-8")
print(f"✅ HTML 픽스처 {len(W)}개 생성: {OUT}")
for name in sorted(W):
    print(f"   · {name}")
